package quality

// Parity-exempt: 生成物标记门禁是 Go 侧仓库卫生护栏。仓库约定所有
// `*_gen.go` 必须以标准头 `// Code generated ... DO NOT EDIT.` 开头，这样
// 编辑器和 review 都能识别"不要手改"；上游 Python 无此约定。

import (
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"
)

// generatedMarkerPattern is the Go convention from https://go.dev/s/generatedcode:
// a line comment matching `^// Code generated .* DO NOT EDIT\.$` before the
// package clause.
var generatedMarkerPattern = regexp.MustCompile(`(?m)^// Code generated .*DO NOT EDIT\.`)

// scanGeneratedMarkers walks the module and reports every `*_gen.go` whose head
// lacks the generated-code marker. Paths are module-relative.
func scanGeneratedMarkers(root string) ([]string, error) {
	var problems []string
	err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.IsDir() {
			name := entry.Name()
			if strings.HasPrefix(name, ".") || name == "testdata" || name == "node_modules" || name == "dist" {
				return fs.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(entry.Name(), "_gen.go") {
			return nil
		}
		data, readErr := os.ReadFile(path)
		if readErr != nil {
			return readErr
		}
		head := data
		if len(head) > 4096 {
			head = head[:4096]
		}
		if !generatedMarkerPattern.Match(head) {
			rel, relErr := filepath.Rel(root, path)
			if relErr != nil {
				return relErr
			}
			problems = append(problems, filepath.ToSlash(rel)+" 缺少 `// Code generated ... DO NOT EDIT.` 头")
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	sort.Strings(problems)
	return problems, nil
}

// Parity-exempt: 生成物标记门禁本体。
func TestGeneratedFileMarkers(t *testing.T) {
	root := moduleRoot(t)
	problems, err := scanGeneratedMarkers(root)
	if err != nil {
		t.Fatalf("扫描 *_gen.go 失败: %v", err)
	}
	if len(problems) > 0 {
		t.Fatalf("生成物缺少标准标记（%d 条）:\n  %s", len(problems), strings.Join(problems, "\n  "))
	}
}

// Parity-exempt: 门禁自检——无头的临时 *_gen.go 必须判定失败，有头必须通过。
func TestGeneratedMarkerGateSelfTest(t *testing.T) {
	dir := t.TempDir()
	pkg := filepath.Join(dir, "internal", "probe")
	if err := os.MkdirAll(pkg, 0o755); err != nil {
		t.Fatal(err)
	}
	bad := filepath.Join(pkg, "bad_gen.go")
	if err := os.WriteFile(bad, []byte("package probe\n\nvar x = 1\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	problems, err := scanGeneratedMarkers(dir)
	if err != nil {
		t.Fatalf("扫描探针根目录失败: %v", err)
	}
	if len(problems) != 1 || !strings.Contains(problems[0], "bad_gen.go") {
		t.Fatalf("无头 *_gen.go 未被判失败: %v", problems)
	}
	good := filepath.Join(pkg, "good_gen.go")
	header := "// Code generated by probe; DO NOT EDIT.\n\npackage probe\n\nvar y = 2\n"
	if err := os.WriteFile(good, []byte(header), 0o644); err != nil {
		t.Fatal(err)
	}
	problems, err = scanGeneratedMarkers(dir)
	if err != nil {
		t.Fatalf("扫描探针根目录失败: %v", err)
	}
	if len(problems) != 1 || !strings.Contains(problems[0], "bad_gen.go") {
		t.Fatalf("带头文件被误报或坏文件漏报: %v", problems)
	}
}
